package edu.bca.futsal.controller;
import jakarta.servlet.http.*; import org.springframework.web.servlet.HandlerInterceptor;
public class AuthInterceptor implements HandlerInterceptor { public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler)throws Exception{var u=(edu.bca.futsal.model.Account)req.getSession().getAttribute("user");if(u==null){res.sendRedirect(req.getContextPath()+"/login");return false;}String path=req.getRequestURI().substring(req.getContextPath().length());boolean organizer=path.equals("/grounds")||path.equals("/bookings")||path.equals("/organizer")||path.equals("/matches")&&"POST".equals(req.getMethod())||path.startsWith("/requests/")&& !path.endsWith("/cancel");boolean player=path.equals("/matches")&&"GET".equals(req.getMethod())||path.equals("/my-requests")||path.endsWith("/join")||path.endsWith("/cancel");if(organizer&& !"ORGANIZER".equals(u.getRole())||player&& !"PLAYER".equals(u.getRole())){res.sendError(403,"This action is not available for your account role.");return false;}return true;} }
